export const recipeExpansionSeeds: RecipeSeed[] = [
  { id:'thai-steamed-fish-ginger', sourceId:'slice2-01', name:'ปลานึ่งขิงซีอิ๊ว', englishName:'Thai Steamed Fish with Ginger', category:'High protein', cuisine:'Thai', servings:2, prepMinutes:12, cookMinutes:15, ingredients:[{item:'White fish fillets',amount:'300 g'},{item:'Ginger, julienned',amount:'2 tbsp'},{item:'Garlic, minced',amount:'2 cloves'},{item:'Reduced-sodium soy sauce',amount:'1 tbsp'},{item:'Lime juice',amount:'1 tbsp'},{item:'Chinese celery, sliced',amount:'½ cup'},{item:'Brown rice, cooked',amount:'1 cup'}], instructions:['Place the fish on a heatproof plate with ginger and garlic.','Steam until the centre is opaque and flakes easily, about 12–15 minutes.','Mix soy sauce with lime juice and spoon it over the hot fish.','Top with Chinese celery and serve with brown rice.'], nutrition:{kcal:300,protein:34,carbs:29,fat:6,fiber:3,sodium:560}, tags:['High protein','Light','Gluten-free'], accent:'aqua' },
  { id:'thai-red-curry-tofu', sourceId:'slice2-02', name:'แกงเผ็ดเต้าหู้ผัก', englishName:'Thai Red Curry Tofu', category:'Plant-forward', cuisine:'Thai', servings:2, prepMinutes:12, cookMinutes:18, ingredients:[{item:'Firm tofu, cubed',amount:'300 g'},{item:'Light coconut milk',amount:'200 ml'},{item:'Red curry paste',amount:'1 tbsp'},{item:'Thai eggplant, quartered',amount:'200 g'},{item:'Bell pepper, sliced',amount:'1 medium'},{item:'Thai basil leaves',amount:'½ cup'},{item:'Brown rice, cooked',amount:'1 cup'}], instructions:['Warm a non-stick pan and stir the curry paste until fragrant.','Add coconut milk and eggplant; simmer until the eggplant is tender.','Fold in tofu and bell pepper and cook gently for 5 minutes.','Turn off the heat, add Thai basil and serve with brown rice.'], nutrition:{kcal:390,protein:20,carbs:43,fat:16,fiber:7,sodium:520}, tags:['Vegetarian','Plant protein','Balanced'], accent:'red' },
  { id:'thai-pork-satay-brown-rice', sourceId:'slice2-03', name:'หมูสะเต๊ะซอสถั่วกับข้าวกล้อง', englishName:'Thai Pork Satay with Brown Rice', category:'High protein', cuisine:'Thai', servings:2, prepMinutes:20, cookMinutes:14, ingredients:[{item:'Lean pork loin, thinly sliced',amount:'300 g'},{item:'Light coconut milk',amount:'2 tbsp'},{item:'Natural peanut butter',amount:'1 tbsp'},{item:'Curry powder',amount:'1 tsp'},{item:'Cucumber, sliced',amount:'1 small'},{item:'Brown rice, cooked',amount:'1 cup'},{item:'Lime juice',amount:'1 tbsp'}], instructions:['Mix pork with coconut milk and curry powder; rest for 10 minutes.','Thread or lay the pork on a tray and grill until browned and cooked through.','Stir peanut butter with lime juice and 2 tablespoons of warm water for a quick sauce.','Serve pork with cucumber, sauce and brown rice.'], nutrition:{kcal:460,protein:38,carbs:40,fat:17,fiber:5,sodium:420}, tags:['High protein','Balanced','Meal prep'], accent:'gold' },
  { id:'thai-pumpkin-chicken-soup', sourceId:'slice2-04', name:'ซุปไก่ฟักทองสมุนไพรไทย', englishName:'Thai Pumpkin Chicken Soup', category:'Light bowls', cuisine:'Thai', servings:2, prepMinutes:12, cookMinutes:22, ingredients:[{item:'Skinless chicken breast, sliced',amount:'260 g'},{item:'Pumpkin, cubed',amount:'300 g'},{item:'Low-sodium stock',amount:'600 ml'},{item:'Mushrooms, sliced',amount:'120 g'},{item:'Lemongrass, bruised',amount:'1 stalk'},{item:'Lime juice',amount:'2 tbsp'},{item:'Coriander leaves',amount:'½ cup'}], instructions:['Simmer stock with lemongrass for 5 minutes.','Add pumpkin and mushrooms and cook until the pumpkin is tender.','Add chicken and poach until fully cooked, about 6 minutes.','Remove the lemongrass, season with lime juice and finish with coriander.'], nutrition:{kcal:290,protein:31,carbs:25,fat:7,fiber:5,sodium:470}, tags:['High protein','Light','Gluten-free'], accent:'gold' },
  { id:'thai-vegetable-pad-see-ew', sourceId:'slice2-05', name:'ผัดซีอิ๊วเส้นข้าวกล้องเต้าหู้', englishName:'Vegetable Pad See Ew with Tofu', category:'Quick meals', cuisine:'Thai', servings:2, prepMinutes:15, cookMinutes:12, ingredients:[{item:'Whole-wheat rice noodles, cooked',amount:'150 g'},{item:'Eggs',amount:'2'},{item:'Chinese broccoli, chopped',amount:'220 g'},{item:'Firm tofu, sliced',amount:'180 g'},{item:'Reduced-sodium dark soy sauce',amount:'1 tbsp'},{item:'Neutral oil',amount:'1 tsp'},{item:'Garlic, minced',amount:'2 cloves'}], instructions:['Heat oil and stir-fry garlic with tofu until lightly golden.','Push tofu aside, scramble the eggs, then add Chinese broccoli.','Add noodles and soy sauce; toss until hot and the greens are tender.','Serve immediately with a squeeze of lime if desired.'], nutrition:{kcal:430,protein:20,carbs:62,fat:12,fiber:6,sodium:620}, tags:['Vegetarian','Quick','Balanced'], accent:'lime' },
  { id:'thai-salmon-nam-jim', sourceId:'slice2-06', name:'แซลมอนย่างน้ำจิ้มมะนาว', englishName:'Thai Grilled Salmon with Lime Sauce', category:'High protein', cuisine:'Thai', servings:2, prepMinutes:12, cookMinutes:14, ingredients:[{item:'Salmon fillets',amount:'280 g'},{item:'Jasmine rice, cooked',amount:'1 cup'},{item:'Cucumber, sliced',amount:'1 small'},{item:'Lime juice',amount:'2 tbsp'},{item:'Fish sauce',amount:'1 tsp'},{item:'Garlic, minced',amount:'1 clove'},{item:'Bird’s eye chilli, sliced',amount:'1'}], instructions:['Grill or pan-sear salmon skin-side down until the fish flakes easily.','Whisk lime juice, fish sauce, garlic and chilli into a sharp dipping sauce.','Rest the salmon for 2 minutes, then portion it.','Serve with jasmine rice, cucumber and the lime sauce.'], nutrition:{kcal:450,protein:31,carbs:35,fat:19,fiber:2,sodium:560}, tags:['High protein','Omega-rich','Gluten-free'], accent:'coral' },
  { id:'thai-shrimp-pumpkin-curry', sourceId:'slice2-07', name:'แกงกะหรี่กุ้งฟักทอง', englishName:'Thai Shrimp and Pumpkin Curry', category:'Quick meals', cuisine:'Thai', servings:2, prepMinutes:12, cookMinutes:18, ingredients:[{item:'Prawns, peeled',amount:'240 g'},{item:'Pumpkin, cubed',amount:'280 g'},{item:'Light coconut milk',amount:'200 ml'},{item:'Red curry paste',amount:'1 tbsp'},{item:'Green beans, cut',amount:'150 g'},{item:'Jasmine rice, cooked',amount:'1 cup'}], instructions:['Stir curry paste in a warm pan until fragrant.','Add coconut milk and pumpkin; simmer until the pumpkin is almost tender.','Add prawns and green beans and cook until the prawns are opaque.','Serve the curry over jasmine rice.'], nutrition:{kcal:390,protein:26,carbs:49,fat:10,fiber:7,sodium:510}, tags:['High protein','Balanced','Quick'], accent:'coral' },
  { id:'thai-lentil-larb', sourceId:'slice2-08', name:'ลาบถั่วเลนทิลสมุนไพร', englishName:'Thai Lentil Larb', category:'Plant-forward', cuisine:'Thai', servings:2, prepMinutes:15, cookMinutes:5, ingredients:[{item:'Green lentils, cooked',amount:'1½ cups'},{item:'Cabbage, shredded',amount:'180 g'},{item:'Mint leaves',amount:'½ cup'},{item:'Shallot, sliced',amount:'¼ cup'},{item:'Lime juice',amount:'2 tbsp'},{item:'Toasted rice powder',amount:'1 tbsp'},{item:'Fish sauce',amount:'1 tsp'}], instructions:['Warm the cooked lentils in a dry pan for 3–4 minutes.','Remove from the heat and toss with lime juice, fish sauce and toasted rice powder.','Fold in shallot and mint.','Serve with crisp shredded cabbage.'], nutrition:{kcal:280,protein:14,carbs:43,fat:6,fiber:13,sodium:500}, tags:['Vegetarian','Vegan','Fiber-rich'], accent:'aqua' },
  { id:'thai-eggplant-tofu-salad', sourceId:'slice2-09', name:'ยำมะเขือยาวเต้าหู้และไข่', englishName:'Thai Eggplant Tofu Salad', category:'Plant-forward', cuisine:'Thai', servings:2, prepMinutes:15, cookMinutes:12, ingredients:[{item:'Firm tofu, cubed',amount:'240 g'},{item:'Thai eggplant, sliced',amount:'250 g'},{item:'Boiled eggs',amount:'2'},{item:'Mint and coriander',amount:'1 cup'},{item:'Lime juice',amount:'2 tbsp'},{item:'Roasted peanuts, chopped',amount:'1 tbsp'}], instructions:['Steam or grill the eggplant until tender and lightly charred.','Pan-sear tofu until golden on two sides.','Mix lime juice with 1 tablespoon of water and toss with the herbs.','Arrange eggplant, tofu and halved eggs, then spoon over the dressing and peanuts.'], nutrition:{kcal:330,protein:22,carbs:25,fat:17,fiber:7,sodium:300}, tags:['Vegetarian','Plant protein','Light'], accent:'violet' },
  { id:'thai-mushroom-cashew-stir-fry', sourceId:'slice2-10', name:'ผัดเห็ดเม็ดมะม่วงหิมพานต์', englishName:'Thai Mushroom and Cashew Stir-fry', category:'Plant-forward', cuisine:'Thai', servings:2, prepMinutes:12, cookMinutes:10, ingredients:[{item:'Mixed mushrooms, sliced',amount:'300 g'},{item:'Unsalted cashews',amount:'30 g'},{item:'Bell pepper, sliced',amount:'1 medium'},{item:'Onion, sliced',amount:'1 medium'},{item:'Reduced-sodium soy sauce',amount:'1 tbsp'},{item:'Neutral oil',amount:'1 tsp'},{item:'Brown rice, cooked',amount:'1 cup'}], instructions:['Toast the cashews in a dry pan and set them aside.','Heat oil and stir-fry onion, pepper and mushrooms until tender.','Add soy sauce and toss until the vegetables are glossy.','Return the cashews and serve with brown rice.'], nutrition:{kcal:390,protein:14,carbs:50,fat:15,fiber:8,sodium:500}, tags:['Vegetarian','Plant protein','Quick'], accent:'gold' },
  { id:'thai-chicken-rice-noodle-soup', sourceId:'slice2-11', name:'ก๋วยเตี๋ยวน้ำไก่ผัก', englishName:'Thai Chicken Rice Noodle Soup', category:'Quick meals', cuisine:'Thai', servings:2, prepMinutes:10, cookMinutes:16, ingredients:[{item:'Skinless chicken breast, sliced',amount:'260 g'},{item:'Rice noodles, dry',amount:'100 g'},{item:'Low-sodium stock',amount:'700 ml'},{item:'Bean sprouts',amount:'1 cup'},{item:'Bok choy, chopped',amount:'180 g'},{item:'Ginger, sliced',amount:'1 tbsp'},{item:'Lime juice',amount:'1 tbsp'}], instructions:['Simmer stock with ginger for 5 minutes.','Add rice noodles and bok choy and cook until just tender.','Add chicken and poach until completely cooked.','Divide between bowls, add bean sprouts and finish with lime juice.'], nutrition:{kcal:360,protein:31,carbs:47,fat:7,fiber:4,sodium:510}, tags:['High protein','Quick','Light'], accent:'blue' },
  { id:'thai-steamed-chicken-cabbage', sourceId:'slice2-12', name:'ไก่นึ่งห่อกะหล่ำปลี', englishName:'Thai Steamed Chicken Cabbage Parcels', category:'High protein', cuisine:'Thai', servings:2, prepMinutes:18, cookMinutes:18, ingredients:[{item:'Lean chicken mince',amount:'280 g'},{item:'Napa cabbage leaves',amount:'8 leaves'},{item:'Shiitake mushrooms, sliced',amount:'120 g'},{item:'Garlic, minced',amount:'2 cloves'},{item:'Oyster sauce',amount:'1 tsp'},{item:'Brown rice, cooked',amount:'1 cup'},{item:'Sesame seeds',amount:'1 tsp'}], instructions:['Blanch cabbage leaves until flexible and pat them dry.','Mix chicken with mushrooms, garlic and oyster sauce.','Wrap the filling in the cabbage leaves and steam for 12–15 minutes.','Sprinkle with sesame and serve with brown rice.'], nutrition:{kcal:390,protein:35,carbs:42,fat:10,fiber:5,sodium:520}, tags:['High protein','Meal prep','Balanced'], accent:'lime' },
  { id:'thai-beef-basil-mushroom', sourceId:'slice2-13', name:'ผัดกะเพราเนื้อใส่เห็ด', englishName:'Thai Beef Basil and Mushroom Stir-fry', category:'High protein', cuisine:'Thai', servings:2, prepMinutes:12, cookMinutes:10, ingredients:[{item:'Lean beef strips',amount:'280 g'},{item:'Mushrooms, sliced',amount:'180 g'},{item:'Thai holy basil',amount:'1 packed cup'},{item:'Long beans, sliced',amount:'120 g'},{item:'Garlic, minced',amount:'2 cloves'},{item:'Bird’s eye chilli, sliced',amount:'1'},{item:'Jasmine rice, cooked',amount:'1 cup'}], instructions:['Stir-fry garlic and chilli in a hot non-stick pan.','Add beef and cook until just browned, then add mushrooms and long beans.','Fold in holy basil and turn off the heat when the leaves wilt.','Serve over jasmine rice.'], nutrition:{kcal:450,protein:35,carbs:46,fat:14,fiber:5,sodium:520}, tags:['High protein','Quick','Balanced'], accent:'red' },
  { id:'thai-coconut-fish-soup', sourceId:'slice2-14', name:'ต้มข่าปลาน้ำใส', englishName:'Thai Coconut Fish Soup', category:'Light bowls', cuisine:'Thai', servings:2, prepMinutes:12, cookMinutes:16, ingredients:[{item:'White fish fillets, cubed',amount:'280 g'},{item:'Light coconut milk',amount:'200 ml'},{item:'Mushrooms, sliced',amount:'150 g'},{item:'Galangal and lemongrass',amount:'1 small bundle'},{item:'Lime juice',amount:'2 tbsp'},{item:'Fish sauce',amount:'1 tsp'},{item:'Jasmine rice, cooked',amount:'1 cup'}], instructions:['Simmer coconut milk with galangal and lemongrass for 5 minutes.','Add mushrooms and cook until softened.','Add fish and poach until opaque and flaky.','Remove the herbs, season with lime juice and fish sauce, and serve with rice.'], nutrition:{kcal:360,protein:31,carbs:32,fat:14,fiber:3,sodium:520}, tags:['High protein','Gluten-free','Light'], accent:'violet' },
  { id:'thai-papaya-tofu-salad', sourceId:'slice2-15', name:'ส้มตำไทยเต้าหู้ย่าง', englishName:'Thai Green Papaya Salad with Grilled Tofu', category:'Plant-forward', cuisine:'Thai', servings:2, prepMinutes:18, cookMinutes:10, ingredients:[{item:'Green papaya, shredded',amount:'300 g'},{item:'Firm tofu, sliced',amount:'240 g'},{item:'Long beans, cut',amount:'100 g'},{item:'Cherry tomatoes, halved',amount:'120 g'},{item:'Lime juice',amount:'2 tbsp'},{item:'Roasted peanuts, chopped',amount:'1 tbsp'},{item:'Fish sauce',amount:'1 tsp'}], instructions:['Grill tofu slices until lightly browned.','Pound or toss papaya, long beans and tomatoes until slightly softened.','Mix lime juice and fish sauce and fold through the salad.','Top with grilled tofu and peanuts.'], nutrition:{kcal:300,protein:20,carbs:32,fat:11,fiber:8,sodium:470}, tags:['Vegetarian','Plant protein','Light'], accent:'lime' },
  { id:'chicken-oyakodon', sourceId:'slice2-16', name:'โอยาโกะด้งไก่และไข่', englishName:'Chicken Oyakodon', category:'High protein', cuisine:'Japanese', servings:2, prepMinutes:10, cookMinutes:16, ingredients:[{item:'Skinless chicken thigh, sliced',amount:'260 g'},{item:'Eggs',amount:'2'},{item:'Onion, thinly sliced',amount:'1 medium'},{item:'Dashi stock',amount:'200 ml'},{item:'Reduced-sodium soy sauce',amount:'1 tbsp'},{item:'Brown rice, cooked',amount:'1 cup'}], instructions:['Simmer onion in dashi and soy sauce until translucent.','Add chicken and cook gently until no longer pink.','Pour in beaten eggs, cover and cook until softly set.','Spoon the chicken and egg over brown rice.'], nutrition:{kcal:470,protein:34,carbs:45,fat:17,fiber:3,sodium:590}, tags:['High protein','Balanced','Quick'], accent:'gold' },
  { id:'salmon-ochazuke', sourceId:'slice2-17', name:'ข้าวชาเขียวแซลมอน', englishName:'Salmon Ochazuke', category:'Quick meals', cuisine:'Japanese', servings:2, prepMinutes:10, cookMinutes:12, ingredients:[{item:'Salmon fillets',amount:'220 g'},{item:'Brown rice, cooked',amount:'1 cup'},{item:'Brewed green tea',amount:'300 ml'},{item:'Nori sheets',amount:'2 sheets'},{item:'Spring onion, sliced',amount:'2 stalks'},{item:'Sesame seeds',amount:'1 tsp'}], instructions:['Pan-sear or bake salmon until it flakes, then break it into large pieces.','Divide warm rice between bowls and top with salmon.','Pour hot green tea around the rice.','Finish with torn nori, spring onion and sesame.'], nutrition:{kcal:390,protein:29,carbs:43,fat:12,fiber:4,sodium:390}, tags:['High protein','Omega-rich','Quick'], accent:'blue' },
  { id:'tofu-yakisoba-vegetables', sourceId:'slice2-18', name:'ยากิโซบะเต้าหู้และผัก', englishName:'Vegetable Yakisoba with Tofu', category:'Plant-forward', cuisine:'Japanese', servings:2, prepMinutes:15, cookMinutes:12, ingredients:[{item:'Whole-wheat noodles, cooked',amount:'160 g'},{item:'Firm tofu, sliced',amount:'260 g'},{item:'Cabbage, shredded',amount:'200 g'},{item:'Carrot, julienned',amount:'1 medium'},{item:'Mushrooms, sliced',amount:'120 g'},{item:'Reduced-sodium yakisoba sauce',amount:'1 tbsp'},{item:'Sesame oil',amount:'1 tsp'}], instructions:['Pan-sear tofu until golden and set it aside.','Stir-fry cabbage, carrot and mushrooms until tender-crisp.','Add noodles and yakisoba sauce and toss until hot.','Return tofu and drizzle with sesame oil before serving.'], nutrition:{kcal:420,protein:21,carbs:58,fat:12,fiber:8,sodium:600}, tags:['Vegetarian','Plant protein','Balanced'], accent:'red' },
  { id:'japanese-cabbage-pork-steam', sourceId:'slice2-19', name:'หมูอบนึ่งกะหล่ำปลีญี่ปุ่น', englishName:'Japanese Steamed Pork and Cabbage', category:'High protein', cuisine:'Japanese', servings:2, prepMinutes:12, cookMinutes:18, ingredients:[{item:'Lean pork loin, thinly sliced',amount:'280 g'},{item:'Napa cabbage, chopped',amount:'250 g'},{item:'Shiitake mushrooms, sliced',amount:'150 g'},{item:'Ginger, julienned',amount:'1 tbsp'},{item:'Ponzu sauce',amount:'2 tbsp'},{item:'Brown rice, cooked',amount:'1 cup'}], instructions:['Layer cabbage, mushrooms, ginger and pork in a steamer basket.','Steam until the pork is fully cooked and the cabbage is tender.','Drizzle ponzu over the hot ingredients.','Serve with brown rice.'], nutrition:{kcal:380,protein:35,carbs:39,fat:11,fiber:6,sodium:610}, tags:['High protein','Meal prep','Light'], accent:'aqua' },
  { id:'cod-daikon-miso', sourceId:'slice2-20', name:'ปลาค็อดต้มไชเท้ามิโสะ', englishName:'Miso Cod with Daikon', category:'High protein', cuisine:'Japanese', servings:2, prepMinutes:12, cookMinutes:22, ingredients:[{item:'Cod fillets',amount:'300 g'},{item:'Daikon, thickly sliced',amount:'300 g'},{item:'White miso',amount:'1 tbsp'},{item:'Dashi stock',amount:'300 ml'},{item:'Ginger, grated',amount:'1 tsp'},{item:'Brown rice, cooked',amount:'1 cup'}], instructions:['Simmer daikon in dashi until it begins to soften.','Whisk miso with a little hot stock and return it to the pot.','Nestle in cod and ginger and simmer until the fish flakes.','Serve the cod and daikon with brown rice and spoon over the broth.'], nutrition:{kcal:360,protein:34,carbs:35,fat:9,fiber:4,sodium:640}, tags:['High protein','Light','Omega-rich'], accent:'violet' },
  { id:'edamame-egg-sushi-bowl', sourceId:'slice2-21', name:'ข้าวซูชิเอเดมาเมะและไข่', englishName:'Edamame Egg Sushi Bowl', category:'Plant-forward', cuisine:'Japanese', servings:2, prepMinutes:15, cookMinutes:10, ingredients:[{item:'Sushi rice, cooked',amount:'1½ cups'},{item:'Eggs',amount:'2'},{item:'Shelled edamame',amount:'140 g'},{item:'Cucumber, sliced',amount:'1 small'},{item:'Carrot, julienned',amount:'1 medium'},{item:'Rice vinegar',amount:'1 tbsp'},{item:'Nori sheets',amount:'2 sheets'}], instructions:['Season warm sushi rice with rice vinegar and cool slightly.','Cook the eggs into a thin omelet, cool and slice.','Build bowls with rice, edamame, cucumber, carrot and omelet.','Top with torn nori and serve.'], nutrition:{kcal:400,protein:20,carbs:59,fat:11,fiber:7,sodium:310}, tags:['Vegetarian','Plant protein','Balanced'], accent:'lime' },
  { id:'soba-tuna-cucumber-bowl', sourceId:'slice2-22', name:'โซบะทูน่าแตงกวา', englishName:'Soba Tuna Cucumber Bowl', category:'Light bowls', cuisine:'Japanese', servings:2, prepMinutes:12, cookMinutes:8, ingredients:[{item:'Buckwheat soba',amount:'150 g'},{item:'Tuna in spring water, drained',amount:'180 g'},{item:'Cucumber, ribbons',amount:'1 small'},{item:'Shelled edamame',amount:'100 g'},{item:'Sesame seeds',amount:'1 tsp'},{item:'Reduced-sodium soy sauce',amount:'1 tbsp'}], instructions:['Cook soba until tender, rinse under cold water and drain well.','Steam edamame for 3 minutes.','Toss soba with tuna, cucumber, edamame and soy sauce.','Finish with sesame seeds and serve chilled.'], nutrition:{kcal:390,protein:31,carbs:51,fat:8,fiber:8,sodium:560}, tags:['High protein','Quick','Dairy-free'], accent:'blue' },
  { id:'japanese-mushroom-chestnut-rice', sourceId:'slice2-23', name:'ข้าวกล้องเห็ดและเกาลัด', englishName:'Japanese Mushroom Chestnut Rice', category:'Plant-forward', cuisine:'Japanese', servings:2, prepMinutes:15, cookMinutes:12, ingredients:[{item:'Brown rice, cooked',amount:'1½ cups'},{item:'Mixed mushrooms, sliced',amount:'250 g'},{item:'Cooked chestnuts',amount:'100 g'},{item:'Carrot, julienned',amount:'1 medium'},{item:'Reduced-sodium soy sauce',amount:'1 tbsp'},{item:'Sesame seeds',amount:'1 tsp'},{item:'Nori sheets',amount:'1 sheet'}], instructions:['Warm mushrooms and carrot in a non-stick pan with 2 tablespoons of water.','Add chestnuts and soy sauce and cook until fragrant.','Fold the mixture through warm brown rice.','Top with sesame and torn nori.'], nutrition:{kcal:360,protein:11,carbs:67,fat:8,fiber:8,sodium:520}, tags:['Vegetarian','Fiber-rich','Meal prep'], accent:'gold' },
  { id:'japanese-sesame-spinach-tofu', sourceId:'slice2-24', name:'เต้าหู้ผักโขมงาคั่ว', englishName:'Japanese Sesame Spinach Tofu', category:'Plant-forward', cuisine:'Japanese', servings:2, prepMinutes:10, cookMinutes:10, ingredients:[{item:'Firm tofu, cubed',amount:'300 g'},{item:'Spinach',amount:'180 g'},{item:'Sesame seeds',amount:'1 tbsp'},{item:'Reduced-sodium soy sauce',amount:'1 tbsp'},{item:'Rice vinegar',amount:'1 tbsp'},{item:'Brown rice, cooked',amount:'1 cup'}], instructions:['Pan-sear tofu until lightly golden.','Wilt spinach in the same pan and remove excess moisture.','Mix soy sauce, vinegar and sesame seeds.','Serve tofu and spinach over brown rice with the sesame dressing.'], nutrition:{kcal:350,protein:24,carbs:34,fat:14,fiber:7,sodium:560}, tags:['Vegetarian','Plant protein','Quick'], accent:'aqua' },
  { id:'japanese-vegetable-udon-broth', sourceId:'slice2-25', name:'อุด้งน้ำผักและเต้าหู้', englishName:'Japanese Vegetable Udon Broth', category:'Light bowls', cuisine:'Japanese', servings:2, prepMinutes:10, cookMinutes:14, ingredients:[{item:'Whole-wheat udon, cooked',amount:'180 g'},{item:'Mushrooms, sliced',amount:'160 g'},{item:'Bok choy, chopped',amount:'180 g'},{item:'Firm tofu, cubed',amount:'180 g'},{item:'Dashi stock',amount:'600 ml'},{item:'Reduced-sodium soy sauce',amount:'1 tbsp'},{item:'Spring onion, sliced',amount:'2 stalks'}], instructions:['Bring dashi and soy sauce to a gentle simmer.','Add mushrooms, bok choy and tofu and cook until tender.','Add udon and warm through for 2 minutes.','Ladle into bowls and top with spring onion.'], nutrition:{kcal:330,protein:18,carbs:50,fat:8,fiber:6,sodium:620}, tags:['Vegetarian','Light','Quick'], accent:'blue' },
  { id:'kimchi-tofu-stew', sourceId:'slice2-26', name:'ซุปกิมจิเต้าหู้ไข่', englishName:'Kimchi Tofu Stew', category:'Plant-forward', cuisine:'Korean', servings:2, prepMinutes:10, cookMinutes:18, ingredients:[{item:'Firm tofu, cubed',amount:'300 g'},{item:'Kimchi, chopped',amount:'150 g'},{item:'Mushrooms, sliced',amount:'120 g'},{item:'Napa cabbage, chopped',amount:'150 g'},{item:'Low-sodium stock',amount:'500 ml'},{item:'Egg',amount:'1'},{item:'Sesame oil',amount:'1 tsp'}], instructions:['Simmer kimchi, stock and mushrooms for 8 minutes.','Add cabbage and tofu and simmer until the cabbage softens.','Crack in the egg and cook until the white is set.','Finish with sesame oil and serve hot.'], nutrition:{kcal:300,protein:22,carbs:18,fat:15,fiber:6,sodium:690}, tags:['Vegetarian','Plant protein','Comforting'], accent:'red' },
  { id:'korean-beef-lettuce-bowl', sourceId:'slice2-27', name:'โบวล์เนื้อเกาหลีห่อผักกาด', englishName:'Korean Beef Lettuce Rice Bowl', category:'High protein', cuisine:'Korean', servings:2, prepMinutes:15, cookMinutes:12, ingredients:[{item:'Lean beef strips',amount:'280 g'},{item:'Brown rice, cooked',amount:'1 cup'},{item:'Lettuce leaves',amount:'8 leaves'},{item:'Carrot, julienned',amount:'1 medium'},{item:'Cucumber, sliced',amount:'1 small'},{item:'Gochujang',amount:'1 tsp'},{item:'Sesame seeds',amount:'1 tsp'}], instructions:['Sear beef in a hot non-stick pan until browned and cooked to your liking.','Stir gochujang with 1 tablespoon of water and toss with the beef.','Arrange rice, carrot, cucumber and lettuce in bowls.','Add the beef and sprinkle with sesame before serving.'], nutrition:{kcal:450,protein:34,carbs:44,fat:15,fiber:6,sodium:560}, tags:['High protein','Balanced','Quick'], accent:'coral' },
  { id:'korean-salmon-rice-bowl', sourceId:'slice2-28', name:'ข้าวหน้าแซลมอนซอสโคชูจัง', englishName:'Korean Salmon Rice Bowl', category:'High protein', cuisine:'Korean', servings:2, prepMinutes:12, cookMinutes:15, ingredients:[{item:'Salmon fillets',amount:'260 g'},{item:'Brown rice, cooked',amount:'1 cup'},{item:'Cucumber, sliced',amount:'1 small'},{item:'Spinach',amount:'120 g'},{item:'Gochujang',amount:'1 tsp'},{item:'Sesame seeds',amount:'1 tsp'}], instructions:['Bake or pan-sear salmon until it flakes easily, then break it into chunks.','Wilt spinach in a hot pan with a splash of water.','Stir gochujang with 1 tablespoon of water for a light sauce.','Serve salmon over rice with spinach, cucumber and sesame.'], nutrition:{kcal:450,protein:31,carbs:44,fat:18,fiber:6,sodium:490}, tags:['High protein','Omega-rich','Balanced'], accent:'aqua' },
  { id:'korean-egg-roll-rice', sourceId:'slice2-29', name:'ข้าวกล้องไข่ม้วนผักเกาหลี', englishName:'Korean Vegetable Egg Roll Rice', category:'Quick meals', cuisine:'Korean', servings:2, prepMinutes:12, cookMinutes:10, ingredients:[{item:'Eggs',amount:'4'},{item:'Carrot, finely diced',amount:'1 medium'},{item:'Spring onion, sliced',amount:'2 stalks'},{item:'Spinach',amount:'100 g'},{item:'Brown rice, cooked',amount:'1 cup'},{item:'Sesame oil',amount:'1 tsp'}], instructions:['Whisk eggs with carrot and spring onion.','Cook in a lightly oiled non-stick pan, rolling the egg into a log as it sets.','Wilt spinach in the warm pan.','Slice the egg roll and serve over brown rice with sesame oil.'], nutrition:{kcal:390,protein:25,carbs:42,fat:14,fiber:5,sodium:420}, tags:['Vegetarian','Balanced','Quick'], accent:'gold' },
  { id:'korean-bean-sprout-chicken-soup', sourceId:'slice2-30', name:'ซุปไก่ถั่วงอกเกาหลี', englishName:'Korean Chicken Bean Sprout Soup', category:'Light bowls', cuisine:'Korean', servings:2, prepMinutes:10, cookMinutes:18, ingredients:[{item:'Skinless chicken breast, sliced',amount:'240 g'},{item:'Bean sprouts',amount:'180 g'},{item:'Napa cabbage, chopped',amount:'150 g'},{item:'Low-sodium stock',amount:'650 ml'},{item:'Garlic, minced',amount:'2 cloves'},{item:'Chilli flakes',amount:'½ tsp'},{item:'Brown rice, cooked',amount:'1 cup'}], instructions:['Bring stock, garlic and chilli flakes to a simmer.','Add chicken and cook until no longer pink.','Add bean sprouts and cabbage and simmer for 3 minutes.','Serve the soup with brown rice.'], nutrition:{kcal:320,protein:30,carbs:38,fat:6,fiber:5,sodium:500}, tags:['High protein','Light','Gluten-free'], accent:'violet' },
  { id:'steamed-chicken-ginger-scallion', sourceId:'slice2-31', name:'ไก่นึ่งขิงต้นหอม', englishName:'Chinese Steamed Chicken with Ginger Scallion', category:'High protein', cuisine:'Chinese', servings:2, prepMinutes:12, cookMinutes:18, ingredients:[{item:'Skinless chicken breast',amount:'300 g'},{item:'Ginger, finely sliced',amount:'2 tbsp'},{item:'Spring onion, sliced',amount:'3 stalks'},{item:'Bok choy',amount:'200 g'},{item:'Reduced-sodium soy sauce',amount:'1 tbsp'},{item:'Brown rice, cooked',amount:'1 cup'}], instructions:['Place chicken on a heatproof plate with half the ginger and steam until cooked through.','Steam bok choy beside the chicken for the last 3 minutes.','Mix soy sauce with the remaining ginger and spring onion.','Slice chicken and spoon over the ginger-scallion sauce; serve with rice.'], nutrition:{kcal:390,protein:38,carbs:40,fat:8,fiber:5,sodium:590}, tags:['High protein','Light','Meal prep'], accent:'lime' },
  { id:'tomato-egg-stir-fry', sourceId:'slice2-32', name:'ผัดมะเขือเทศใส่ไข่', englishName:'Chinese Tomato Egg Stir-fry', category:'Plant-forward', cuisine:'Chinese', servings:2, prepMinutes:8, cookMinutes:10, ingredients:[{item:'Eggs',amount:'4'},{item:'Tomatoes, cut into wedges',amount:'350 g'},{item:'Spinach',amount:'100 g'},{item:'Neutral oil',amount:'1 tsp'},{item:'Reduced-sodium soy sauce',amount:'1 tsp'},{item:'Brown rice, cooked',amount:'1 cup'}], instructions:['Whisk eggs and gently scramble them in a non-stick pan; set aside.','Cook tomatoes until juicy, then add spinach to wilt.','Return the eggs and season with soy sauce.','Serve over brown rice.'], nutrition:{kcal:340,protein:20,carbs:40,fat:11,fiber:5,sodium:430}, tags:['Vegetarian','Quick','Balanced'], accent:'coral' },
  { id:'black-pepper-beef-vegetables', sourceId:'slice2-33', name:'เนื้อผัดพริกไทยดำกับผัก', englishName:'Chinese Black Pepper Beef and Vegetables', category:'High protein', cuisine:'Chinese', servings:2, prepMinutes:12, cookMinutes:12, ingredients:[{item:'Lean beef strips',amount:'280 g'},{item:'Broccoli florets',amount:'220 g'},{item:'Bell pepper, sliced',amount:'1 medium'},{item:'Onion, sliced',amount:'1 small'},{item:'Reduced-sodium soy sauce',amount:'1 tbsp'},{item:'Ground black pepper',amount:'1 tsp'},{item:'Brown rice, cooked',amount:'1 cup'}], instructions:['Sear beef in a hot non-stick pan until just browned; set it aside.','Stir-fry broccoli, pepper and onion with 3 tablespoons of water.','Return beef and toss with soy sauce and black pepper.','Serve with brown rice while the vegetables are crisp-tender.'], nutrition:{kcal:440,protein:35,carbs:42,fat:14,fiber:7,sodium:560}, tags:['High protein','Balanced','Quick'], accent:'red' },
  { id:'light-mapo-tofu', sourceId:'slice2-34', name:'เต้าหู้มาโปหมูไม่มัน', englishName:'Light Mapo Tofu', category:'Plant-forward', cuisine:'Chinese', servings:2, prepMinutes:12, cookMinutes:16, ingredients:[{item:'Firm tofu, cubed',amount:'300 g'},{item:'Lean pork mince',amount:'120 g'},{item:'Mushrooms, finely chopped',amount:'120 g'},{item:'Tomato, diced',amount:'1 medium'},{item:'Chilli bean paste',amount:'1 tbsp'},{item:'Brown rice, cooked',amount:'1 cup'},{item:'Spring onion, sliced',amount:'2 stalks'}], instructions:['Brown the pork in a non-stick pan, then add mushrooms and cook until tender.','Stir in chilli bean paste and tomato with 3 tablespoons of water.','Fold in tofu and simmer gently for 5 minutes without breaking the cubes.','Top with spring onion and serve over brown rice.'], nutrition:{kcal:430,protein:28,carbs:44,fat:15,fiber:6,sodium:720}, tags:['High protein','Balanced','Quick'], accent:'violet' },
  { id:'vietnamese-shrimp-rice-paper-rolls', sourceId:'slice2-35', name:'ปอเปี๊ยะสดเวียดนามไส้กุ้ง', englishName:'Vietnamese Shrimp Rice Paper Rolls', category:'Light bowls', cuisine:'Vietnamese', servings:2, prepMinutes:20, cookMinutes:6, ingredients:[{item:'Shrimp, peeled',amount:'220 g'},{item:'Rice paper sheets',amount:'6 sheets'},{item:'Rice vermicelli, cooked',amount:'80 g'},{item:'Lettuce leaves',amount:'6 leaves'},{item:'Cucumber, sliced',amount:'1 small'},{item:'Mint and coriander',amount:'1 cup'},{item:'Peanut-lime sauce',amount:'2 tbsp'}], instructions:['Poach shrimp until pink and opaque, then cool and halve lengthwise.','Dip rice paper briefly in warm water until pliable.','Layer lettuce, noodles, cucumber, herbs and shrimp on each sheet.','Roll tightly and serve with peanut-lime sauce.'], nutrition:{kcal:330,protein:23,carbs:43,fat:9,fiber:4,sodium:420}, tags:['High protein','Light','No-cook'], accent:'aqua' },
  { id:'vietnamese-chicken-pho', sourceId:'slice2-36', name:'เฝอไก่เวียดนาม', englishName:'Vietnamese Chicken Pho', category:'Light bowls', cuisine:'Vietnamese', servings:2, prepMinutes:12, cookMinutes:20, ingredients:[{item:'Skinless chicken breast',amount:'260 g'},{item:'Rice noodles, dry',amount:'120 g'},{item:'Low-sodium stock',amount:'700 ml'},{item:'Bean sprouts',amount:'1 cup'},{item:'Thai basil leaves',amount:'½ cup'},{item:'Lime juice',amount:'2 tbsp'},{item:'Ginger, sliced',amount:'1 tbsp'}], instructions:['Simmer stock with ginger for 10 minutes.','Add chicken and poach until fully cooked, then slice it.','Cook rice noodles in the hot broth until tender.','Divide into bowls and top with bean sprouts, basil and lime juice.'], nutrition:{kcal:380,protein:31,carbs:52,fat:6,fiber:4,sodium:550}, tags:['High protein','Light','Gluten-free'], accent:'blue' },
  { id:'chinese-steamed-cod-bok-choy', sourceId:'slice2-37', name:'ปลาค็อดนึ่งผักกวางตุ้ง', englishName:'Chinese Steamed Cod with Bok Choy', category:'High protein', cuisine:'Chinese', servings:2, prepMinutes:10, cookMinutes:15, ingredients:[{item:'Cod fillets',amount:'300 g'},{item:'Bok choy, halved',amount:'240 g'},{item:'Ginger, sliced',amount:'1 tbsp'},{item:'Spring onion, sliced',amount:'2 stalks'},{item:'Reduced-sodium soy sauce',amount:'1 tbsp'},{item:'Sesame oil',amount:'1 tsp'},{item:'Brown rice, cooked',amount:'1 cup'}], instructions:['Steam cod with ginger until it flakes easily.','Steam bok choy alongside for the final 3 minutes.','Drizzle fish with soy sauce and sesame oil.','Top with spring onion and serve with rice.'], nutrition:{kcal:360,protein:36,carbs:39,fat:8,fiber:5,sodium:600}, tags:['High protein','Light','Omega-rich'], accent:'lime' },
  { id:'chinese-chickpea-broccoli-fried-rice', sourceId:'slice2-38', name:'ข้าวผัดถั่วชิกพีบรอกโคลี', englishName:'Chinese Chickpea Broccoli Fried Rice', category:'Plant-forward', cuisine:'Chinese', servings:2, prepMinutes:12, cookMinutes:12, ingredients:[{item:'Brown rice, cooked',amount:'1½ cups'},{item:'Chickpeas, rinsed',amount:'1 cup'},{item:'Broccoli florets',amount:'180 g'},{item:'Eggs',amount:'2'},{item:'Green peas',amount:'½ cup'},{item:'Reduced-sodium soy sauce',amount:'1 tbsp'},{item:'Neutral oil',amount:'1 tsp'}], instructions:['Scramble eggs in the oil and move them to one side of the pan.','Add broccoli, chickpeas and peas and stir-fry until hot.','Fold in rice and soy sauce and toss until steaming.','Mix the egg through and serve.'], nutrition:{kcal:450,protein:20,carbs:70,fat:12,fiber:12,sodium:560}, tags:['Vegetarian','Fiber-rich','Balanced'], accent:'gold' },
  { id:'baked-cod-lemon-herbs', sourceId:'slice2-39', name:'ปลาค็อดอบมะนาวสมุนไพร', englishName:'Mediterranean Baked Cod with Lemon Herbs', category:'High protein', cuisine:'Mediterranean', servings:2, prepMinutes:12, cookMinutes:18, ingredients:[{item:'Cod fillets',amount:'320 g'},{item:'Quinoa, cooked',amount:'1 cup'},{item:'Zucchini, sliced',amount:'1 medium'},{item:'Cherry tomatoes',amount:'150 g'},{item:'Olive oil',amount:'1 tsp'},{item:'Lemon juice',amount:'2 tbsp'},{item:'Parsley, chopped',amount:'½ cup'}], instructions:['Place cod, zucchini and tomatoes on a lined tray.','Brush with olive oil and bake at 200°C until the cod flakes.','Drizzle with lemon juice and scatter parsley over the tray.','Serve with warm quinoa.'], nutrition:{kcal:390,protein:37,carbs:34,fat:10,fiber:6,sodium:300}, tags:['High protein','Light','Gluten-free'], accent:'aqua' },
  { id:'turkey-meatballs-tomato-quinoa', sourceId:'slice2-40', name:'มีทบอลไก่งวงซอสมะเขือเทศกับควินัว', englishName:'Turkey Meatballs with Tomato Quinoa', category:'High protein', cuisine:'Mediterranean', servings:2, prepMinutes:20, cookMinutes:22, ingredients:[{item:'Lean turkey mince',amount:'300 g'},{item:'Quinoa, cooked',amount:'1 cup'},{item:'Crushed tomatoes',amount:'300 g'},{item:'Onion, finely diced',amount:'1 small'},{item:'Egg',amount:'1'},{item:'Spinach',amount:'100 g'},{item:'Olive oil',amount:'1 tsp'}], instructions:['Mix turkey, onion and egg and shape into small meatballs.','Brown them in a non-stick pan, then add crushed tomatoes.','Cover and simmer until the meatballs are cooked through.','Fold spinach into the sauce and serve with quinoa.'], nutrition:{kcal:440,protein:36,carbs:43,fat:14,fiber:7,sodium:460}, tags:['High protein','Balanced','Meal prep'], accent:'red' },
  { id:'lentil-quinoa-herb-salad', sourceId:'slice2-41', name:'สลัดเลนทิลควินัวสมุนไพร', englishName:'Lentil Quinoa Herb Salad', category:'Plant-forward', cuisine:'Mediterranean', servings:2, prepMinutes:15, cookMinutes:0, ingredients:[{item:'Green lentils, cooked',amount:'1½ cups'},{item:'Quinoa, cooked',amount:'1 cup'},{item:'Cucumber, diced',amount:'1 small'},{item:'Tomatoes, diced',amount:'2 medium'},{item:'Parsley and mint',amount:'1 cup'},{item:'Lemon juice',amount:'2 tbsp'},{item:'Feta cheese, crumbled',amount:'40 g'}], instructions:['Combine lentils, quinoa, cucumber and tomatoes in a wide bowl.','Whisk lemon juice with 1 tablespoon of water and black pepper.','Toss the dressing through the salad and fold in the herbs.','Scatter with feta and serve cool or at room temperature.'], nutrition:{kcal:390,protein:19,carbs:56,fat:10,fiber:14,sodium:420}, tags:['Vegetarian','Fiber-rich','No-cook'], accent:'lime' },
  { id:'white-bean-tomato-soup', sourceId:'slice2-42', name:'ซุปถั่วขาวมะเขือเทศและผักโขม', englishName:'White Bean Tomato Spinach Soup', category:'Plant-forward', cuisine:'Mediterranean', servings:2, prepMinutes:12, cookMinutes:20, ingredients:[{item:'Cannellini beans, rinsed',amount:'1½ cups'},{item:'Tomatoes, chopped',amount:'400 g'},{item:'Carrot, diced',amount:'1 medium'},{item:'Spinach',amount:'100 g'},{item:'Low-sodium stock',amount:'600 ml'},{item:'Olive oil',amount:'1 tsp'},{item:'Whole-wheat bread',amount:'2 slices'}], instructions:['Warm olive oil and soften carrot in a pot.','Add tomatoes, beans and stock and simmer for 15 minutes.','Stir in spinach until just wilted.','Serve the soup with toasted whole-wheat bread.'], nutrition:{kcal:330,protein:15,carbs:54,fat:8,fiber:14,sodium:480}, tags:['Vegan','Fiber-rich','Comforting'], accent:'coral' },
  { id:'tuna-white-bean-salad', sourceId:'slice2-43', name:'สลัดทูน่าถั่วขาวเมดิเตอร์เรเนียน', englishName:'Mediterranean Tuna White Bean Salad', category:'Light bowls', cuisine:'Mediterranean', servings:2, prepMinutes:12, cookMinutes:0, ingredients:[{item:'Tuna in spring water, drained',amount:'200 g'},{item:'White beans, rinsed',amount:'1 cup'},{item:'Rocket leaves',amount:'100 g'},{item:'Tomato, diced',amount:'1 medium'},{item:'Red onion, sliced',amount:'¼ cup'},{item:'Olive oil',amount:'1 tsp'},{item:'Lemon juice',amount:'2 tbsp'}], instructions:['Combine tuna, beans, rocket, tomato and onion.','Whisk olive oil with lemon juice and black pepper.','Toss the dressing gently through the salad.','Serve immediately while the rocket is crisp.'], nutrition:{kcal:330,protein:32,carbs:30,fat:10,fiber:9,sodium:430}, tags:['High protein','Light','No-cook'], accent:'aqua' },
  { id:'roasted-vegetable-couscous', sourceId:'slice2-44', name:'คูสคูสผักย่างกับถั่วชิกพี', englishName:'Roasted Vegetable Couscous with Chickpeas', category:'Plant-forward', cuisine:'Mediterranean', servings:2, prepMinutes:15, cookMinutes:24, ingredients:[{item:'Whole-wheat couscous, cooked',amount:'150 g'},{item:'Chickpeas, rinsed',amount:'1 cup'},{item:'Zucchini, sliced',amount:'1 medium'},{item:'Bell pepper, sliced',amount:'1 medium'},{item:'Cherry tomatoes',amount:'150 g'},{item:'Olive oil',amount:'1 tsp'},{item:'Lemon juice',amount:'1 tbsp'}], instructions:['Roast zucchini, pepper and tomatoes at 200°C until tender and lightly browned.','Warm chickpeas in the tray for the last 5 minutes.','Fluff couscous and toss with the roasted vegetables.','Finish with lemon juice and serve.'], nutrition:{kcal:430,protein:16,carbs:70,fat:12,fiber:13,sodium:350}, tags:['Vegan','Fiber-rich','Meal prep'], accent:'gold' },
  { id:'mushroom-barley-bowl', sourceId:'slice2-45', name:'โบวล์ข้าวบาร์เลย์เห็ดและถั่วเลนทิล', englishName:'Mushroom Barley Lentil Bowl', category:'Plant-forward', cuisine:'International', servings:2, prepMinutes:12, cookMinutes:15, ingredients:[{item:'Pearl barley, cooked',amount:'1½ cups'},{item:'Mixed mushrooms, sliced',amount:'250 g'},{item:'Green lentils, cooked',amount:'1 cup'},{item:'Spinach',amount:'100 g'},{item:'Low-sodium stock',amount:'200 ml'},{item:'Olive oil',amount:'1 tsp'},{item:'Parsley, chopped',amount:'½ cup'}], instructions:['Warm olive oil and cook mushrooms until they release their moisture.','Add stock and barley and simmer until hot.','Fold in lentils and spinach until the spinach wilts.','Top with parsley and serve in bowls.'], nutrition:{kcal:410,protein:21,carbs:66,fat:10,fiber:15,sodium:360}, tags:['Vegan','Fiber-rich','Meal prep'], accent:'violet' },
  { id:'spinach-feta-frittata', sourceId:'slice2-46', name:'ฟริตตาตาผักโขมเฟต้า', englishName:'Spinach Mushroom Feta Frittata', category:'Quick meals', cuisine:'International', servings:2, prepMinutes:10, cookMinutes:15, ingredients:[{item:'Eggs',amount:'4'},{item:'Spinach',amount:'150 g'},{item:'Mushrooms, sliced',amount:'150 g'},{item:'Feta cheese, crumbled',amount:'50 g'},{item:'Cherry tomatoes, halved',amount:'120 g'},{item:'Olive oil',amount:'1 tsp'},{item:'Whole-wheat bread',amount:'2 slices'}], instructions:['Cook mushrooms and spinach in olive oil until the spinach wilts.','Whisk eggs and pour them into the pan, then scatter feta and tomatoes over the top.','Cook over low heat until the edges set, then finish under a grill until firm.','Slice and serve with whole-wheat bread.'], nutrition:{kcal:390,protein:25,carbs:28,fat:19,fiber:5,sodium:620}, tags:['Vegetarian','Balanced','Quick'], accent:'gold' },
  { id:'shakshuka-whole-wheat-toast', sourceId:'slice2-47', name:'ชักชูก้ากับขนมปังโฮลวีต', englishName:'Shakshuka with Whole-Wheat Toast', category:'Quick meals', cuisine:'Mediterranean', servings:2, prepMinutes:10, cookMinutes:20, ingredients:[{item:'Eggs',amount:'4'},{item:'Crushed tomatoes',amount:'400 g'},{item:'Bell pepper, diced',amount:'1 medium'},{item:'Onion, diced',amount:'1 small'},{item:'Chickpeas, rinsed',amount:'½ cup'},{item:'Olive oil',amount:'1 tsp'},{item:'Whole-wheat bread',amount:'2 slices'}], instructions:['Soften onion and pepper in olive oil.','Add tomatoes and chickpeas and simmer until thickened.','Make four wells, crack in the eggs, cover and cook until the whites set.','Serve with toasted whole-wheat bread.'], nutrition:{kcal:420,protein:24,carbs:50,fat:15,fiber:11,sodium:540}, tags:['Vegetarian','Fiber-rich','Balanced'], accent:'red' },
  { id:'overnight-oats-berry-chia', sourceId:'slice2-48', name:'โอเวอร์ไนท์โอ๊ตเบอร์รีและเมล็ดเจีย', englishName:'Berry Chia Overnight Oats', category:'Quick meals', cuisine:'American', servings:2, prepMinutes:10, cookMinutes:0, ingredients:[{item:'Rolled oats',amount:'1 cup'},{item:'Plain Greek yogurt',amount:'170 g'},{item:'Mixed berries',amount:'1 cup'},{item:'Chia seeds',amount:'1 tbsp'},{item:'Low-fat milk',amount:'200 ml'},{item:'Cinnamon',amount:'a pinch'}], instructions:['Stir oats, yogurt, milk, chia and cinnamon in a container.','Fold in half of the berries.','Cover and chill overnight or for at least 4 hours.','Top with the remaining berries before serving.'], nutrition:{kcal:360,protein:18,carbs:55,fat:9,fiber:10,sodium:120}, tags:['Vegetarian','Fiber-rich','No-cook'], accent:'coral' },
  { id:'hummus-chicken-pita', sourceId:'slice2-49', name:'พิต้าไก่ย่างฮัมมัส', englishName:'Hummus Chicken Pita', category:'High protein', cuisine:'Mediterranean', servings:2, prepMinutes:15, cookMinutes:14, ingredients:[{item:'Skinless chicken breast, sliced',amount:'260 g'},{item:'Whole-wheat pita',amount:'2 medium'},{item:'Hummus',amount:'½ cup'},{item:'Cucumber, sliced',amount:'1 small'},{item:'Tomato, sliced',amount:'1 medium'},{item:'Lettuce leaves',amount:'4 leaves'},{item:'Lemon juice',amount:'1 tbsp'}], instructions:['Pan-sear chicken with lemon juice until cooked through, then slice.','Warm the pita briefly and spread with hummus.','Fill with lettuce, cucumber, tomato and chicken.','Fold and serve immediately.'], nutrition:{kcal:460,protein:36,carbs:52,fat:13,fiber:10,sodium:690}, tags:['High protein','Balanced','Quick'], accent:'lime' },
  { id:'black-bean-sweet-potato-chili', sourceId:'slice2-50', name:'ชิลีถั่วดำมันหวาน', englishName:'Black Bean Sweet Potato Chili', category:'Plant-forward', cuisine:'Mexican', servings:2, prepMinutes:15, cookMinutes:28, ingredients:[{item:'Black beans, rinsed',amount:'1½ cups'},{item:'Sweet potato, cubed',amount:'300 g'},{item:'Tomatoes, chopped',amount:'400 g'},{item:'Bell pepper, diced',amount:'1 medium'},{item:'Corn kernels',amount:'½ cup'},{item:'Olive oil',amount:'1 tsp'},{item:'Brown rice, cooked',amount:'1 cup'}], instructions:['Soften bell pepper in olive oil in a deep pot.','Add sweet potato, tomatoes and 200 ml water and simmer until tender.','Stir in black beans and corn and warm through.','Serve the chili over brown rice.'], nutrition:{kcal:450,protein:16,carbs:76,fat:10,fiber:17,sodium:420}, tags:['Vegan','Fiber-rich','Comforting'], accent:'red' },
]

